import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { emitTables } from '../src/emit/tables.ts';
import { syntheticIr } from './support/synthetic-ir.ts';

describe('emit/tables', () => {
  // source: design §7.4 (tables emitter: internal static class CatalogTables with FrozenDictionary rows;
  // header "// <auto-generated/> flint-chart <version>", LF, no timestamp) and §10.4 test 4; the encoding categories
  // of each semantic type and the option labels are what the validator needs to mirror upstream (§6)
  it('emits CatalogTables.g.cs for one chart type on two backends', () => {
    const result = emitTables(syntheticIr());
    assert.deepEqual(result.files.map((f) => f.path), ['Tables/CatalogTables.g.cs']);
    assert.equal(
      result.files[0].content,
      `// <auto-generated/> flint-chart 0.5.1
#nullable enable

using System.Collections.Frozen;

namespace Graspea.Flint;

internal static partial class CatalogTables
{
    internal static readonly FlintBackend[] Backends = [FlintBackend.VegaLite, FlintBackend.Excel];

    internal static readonly FrozenSet<FlintBackend> BackendsApplyingTheme = BackendSet(FlintBackend.VegaLite);

    internal static readonly FrozenSet<string> HostStateKeys = NameSet("sort");

    internal static readonly FrozenDictionary<string, FrozenSet<FlintBackend>> IgnoredOptions = ByName(
        ("maxStretchX", BackendSet(FlintBackend.VegaLite)));

    internal static readonly FrozenSet<string> Channels = NameSet("x", "y", "color");

    internal static readonly FrozenDictionary<string, string[]> SemanticTypes = ByName(
        ("YearMonth", Names("temporal", "ordinal")));

    internal static readonly FrozenSet<string> ThemePresets = NameSet("powerbi-light");

    internal static readonly FrozenDictionary<string, FrozenDictionary<FlintBackend, TemplateRow>> ChartTypes = ByName(
        ("Line Chart", ByBackend(
            (FlintBackend.VegaLite, new TemplateRow(
                ["x", "y", "color"],
                [
                    new PropertyRow("interpolate", PropertyKind.Discrete, Options: [null, "\\"monotone\\""], Labels: ["Default", "Monotone"]),
                    new PropertyRow("showPoints", PropertyKind.Binary),
                    new PropertyRow("strokeWidth", PropertyKind.Continuous, Min: 0.5, Max: 5, Step: 0.5),
                ])),
            (FlintBackend.Excel, new TemplateRow(
                ["x", "y"],
                [],
                supportsFacets: false,
                hasValidate: true)))));

    internal static readonly FrozenDictionary<string, string> Retired = ByName<string>();
}
`,
    );
  });

  // source: design §7.8 and part 3 §8.4 (the validator reports retired_member from the ledger, naming the version; every
  // entry counts, also one whose facade member was removed)
  it('lists every retired IR path with the version that retired it', () => {
    const ir = syntheticIr();
    ir.retired = [
      { path: 'catalog.chartTypes[Line Chart].backends.vegalite.properties[smooth]', lastSeenIn: '0.4.0', retiredIn: '0.4.1', deletedIn: '0.5.0' },
      { path: 'catalog.semanticTypes[Week]', lastSeenIn: '0.5.0', retiredIn: '0.5.1', was: { name: 'Week' } },
    ];
    assert.ok(
      emitTables(ir).files[0].content.includes(
        '    internal static readonly FrozenDictionary<string, string> Retired = ByName(\n' +
          '        ("catalog.chartTypes[Line Chart].backends.vegalite.properties[smooth]", "0.4.1"),\n' +
          '        ("catalog.semanticTypes[Week]", "0.5.1"));\n',
      ),
    );
  });

  // source: design §7.4 (no timestamps; output depends only on the IR)
  it('is deterministic', () => {
    assert.equal(emitTables(syntheticIr()).files[0].content, emitTables(syntheticIr()).files[0].content);
  });

  // source: design §3 (FlintBackend is hand-written; an unknown backend id cannot be mapped)
  it('fails on a backend id that FlintBackend does not know', () => {
    const ir = syntheticIr();
    ir.catalog.backends.push('svg');
    assert.throws(() => emitTables(ir), /catalog\.backends\[svg\]/);
  });

  // source: design §7.4 (internal tables are not public API)
  it('declares no public API', () => {
    assert.deepEqual(emitTables(syntheticIr()).apiLines, []);
  });
});
